namespace sv_89c8b03e1b1c4d22b9b03ad79e469945.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — each SignalR circuit (user session) gets its own instance.
/// Static SSR requests also get a per-request instance, but that's fine because
/// the JS interop handles the actual DOM theming.
/// </summary>
public class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        Theme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        AccentColor = color;
        OnChange?.Invoke();
    }

    public void SetAll(ThemeMode theme, string accentColor)
    {
        Theme = theme;
        AccentColor = accentColor;
        OnChange?.Invoke();
    }
}

