// Manages theme application on the DOM and cookie persistence.
// Called from interactive Blazor components via JS interop.
export function applyTheme(theme, accentColor) {
    const root = document.documentElement;

    root.classList.remove('theme-light', 'theme-dark', 'theme-system');
    root.classList.add(`theme-${theme.toLowerCase()}`);

    if (theme === 'Dark') {
        root.setAttribute('data-bs-theme', 'dark');
    } else if (theme === 'Light') {
        root.setAttribute('data-bs-theme', 'light');
    } else {
        // System: follow prefers-color-scheme
        const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
        root.setAttribute('data-bs-theme', prefersDark ? 'dark' : 'light');
    }

    root.style.setProperty('--accent-color', accentColor);

    // Persist to cookie so SSR can read it on next navigation
    const expires = new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toUTCString();
    document.cookie = `theme=${theme};path=/;expires=${expires};SameSite=Lax`;
    document.cookie = `accentColor=${encodeURIComponent(accentColor)};path=/;expires=${expires};SameSite=Lax`;
}

export function getStoredTheme() {
    const cookies = Object.fromEntries(
        document.cookie.split('; ').filter(c => c).map(c => {
            const [k, ...v] = c.split('=');
            return [k, decodeURIComponent(v.join('='))];
        })
    );
    return {
        theme: cookies['theme'] || 'System',
        accentColor: cookies['accentColor'] || '#0d6efd'
    };
}

