@using sv_89c8b03e1b1c4d22b9b03ad79e469945.Services
@implements IAsyncDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

<span class="theme-indicator" title="Current theme: @ThemeService.Theme">
    @GetThemeIcon() <span class="d-none d-sm-inline">@ThemeService.Theme</span>
    <button class="btn btn-sm btn-outline-secondary ms-2" @onclick="CycleTheme">
        Toggle
    </button>
</span>

@code {
    private IJSObjectReference? _module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./js/theme.js");

            // Read stored theme from cookies and sync into service
            var stored = await _module.InvokeAsync<StoredTheme>("getStoredTheme");
            if (Enum.TryParse<ThemeMode>(stored.Theme, out var mode))
            {
                ThemeService.SetAll(mode, stored.AccentColor ?? "#0d6efd");
            }

            // Apply the current theme to the DOM
            await ApplyThemeToDOM();

            ThemeService.OnChange += OnThemeChanged;
            StateHasChanged();
        }
    }

    private string GetThemeIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    private async Task CycleTheme()
    {
        var next = ThemeService.Theme switch
        {
            ThemeMode.Light => ThemeMode.Dark,
            ThemeMode.Dark => ThemeMode.System,
            _ => ThemeMode.Light
        };
        ThemeService.SetTheme(next);
    }

    private async void OnThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyThemeToDOM();
            StateHasChanged();
        });
    }

    private async Task ApplyThemeToDOM()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("applyTheme",
                ThemeService.Theme.ToString(), ThemeService.AccentColor);
        }
    }

    public async ValueTask DisposeAsync()
    {
        ThemeService.OnChange -= OnThemeChanged;
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
    }

    private record StoredTheme(string Theme, string? AccentColor);
}

