+@page "/settings"
+@rendermode InteractiveServer
+@using sv_89c8b03e1b1c4d22b9b03ad79e469945.Services
+@implements IAsyncDisposable
+@inject ThemeService ThemeService
+@inject IJSRuntime JS
+
+<PageTitle>User Preferences</PageTitle>
+
+<h1>User Preferences</h1>
+
+<div class="card mt-3" style="max-width: 500px;">
+    <div class="card-body">
+        <h5 class="card-title">Theme</h5>
+
+        <div class="btn-group mb-3" role="group">
+            @foreach (var mode in Enum.GetValues<ThemeMode>())
+            {
+                <button type="button"
+                        class="btn @(ThemeService.Theme == mode ? "btn-primary" : "btn-outline-primary")"
+                        @onclick="() => SetTheme(mode)">
+                    @mode
+                </button>
+            }
+        </div>
+
+        <h5 class="card-title">Accent Color</h5>
+        <div class="d-flex align-items-center gap-3 mb-3">
+            <input type="color" class="form-control form-control-color"
+                   value="@ThemeService.AccentColor"
+                   @onchange="OnAccentColorChanged" />
+            <span>@ThemeService.AccentColor</span>
+        </div>
+
+        <div class="alert alert-info mt-3">
+            Current theme: <strong>@ThemeService.Theme</strong> —
+            Accent: <span style="color: @ThemeService.AccentColor; font-weight: bold;">
+                @ThemeService.AccentColor
+            </span>
+        </div>
+    </div>
+</div>
+
+@code {
+    private IJSObjectReference? _module;
+
+    protected override async Task OnAfterRenderAsync(bool firstRender)
+    {
+        if (firstRender)
+        {
+            _module = await JS.InvokeAsync<IJSObjectReference>(
+                "import", "./js/theme.js");
+
+            ThemeService.OnChange += OnThemeChanged;
+        }
+    }
+
+    private async Task SetTheme(ThemeMode mode)
+    {
+        ThemeService.SetTheme(mode);
+    }
+
+    private async Task OnAccentColorChanged(ChangeEventArgs e)
+    {
+        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
+    }
+
+    private async void OnThemeChanged()
+    {
+        await InvokeAsync(async () =>
+        {
+            await ApplyThemeToDOM();
+            StateHasChanged();
+        });
+    }
+
+    private async Task ApplyThemeToDOM()
+    {
+        if (_module is not null)
+        {
+            await _module.InvokeVoidAsync("applyTheme",
+                ThemeService.Theme.ToString(), ThemeService.AccentColor);
+        }
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        ThemeService.OnChange -= OnThemeChanged;
+        if (_module is not null)
+        {
+            await _module.DisposeAsync();
+        }
+    }
+}
+

